fn sum(v: &Vec[Int]) -> Int {
  let total = 0;
  for item in v {
    total = total + item;
  }
  return total;
}

fn main() -> Int {
  let data = Vec[Int].new();
  data.push(5);
  data.push(10);
  data.push(15);
  let result = sum(&data);
  io.println(data.len());
  return result;
}
